-- AnySports 0.2.0: Supabase SQL Editor에서 전체를 실행하세요.
create table if not exists public.leagues (id text primary key, name text not null, sport text not null, color text not null, sort_order integer not null default 0);
create table if not exists public.entities (id text primary key, league_id text not null references public.leagues(id) on delete cascade, name text not null, short_name text not null, color text not null, role text not null check (role in ('team','constructor','observer')), sort_order integer not null default 0);
create table if not exists public.competitions (id text primary key, league_id text not null references public.leagues(id) on delete cascade, name text not null, is_international boolean not null default false);
create table if not exists public.events (id text primary key, league_id text not null references public.leagues(id) on delete cascade, competition_id text not null references public.competitions(id), source_id text unique, title text not null, subtitle text not null default '', starts_at timestamptz not null, venue text, status text not null default 'scheduled' check (status in ('scheduled','completed','postponed')), result text, source_url text, updated_at timestamptz not null default now());
create table if not exists public.event_entities (event_id text not null references public.events(id) on delete cascade, entity_id text not null references public.entities(id) on delete cascade, primary key(event_id,entity_id));
create table if not exists public.articles (id text primary key, league_id text not null references public.leagues(id), source_id text unique, title text not null, summary text not null default '', source text not null, source_url text, published_at timestamptz not null, accent text not null default '#55E6B1', category text not null default '소식', updated_at timestamptz not null default now());
create table if not exists public.article_entities (article_id text not null references public.articles(id) on delete cascade, entity_id text not null references public.entities(id) on delete cascade, primary key(article_id,entity_id));
create table if not exists public.user_follows (user_id uuid not null references auth.users(id) on delete cascade, entity_id text not null references public.entities(id), primary key(user_id,entity_id));
create table if not exists public.user_preferences (user_id uuid primary key references auth.users(id) on delete cascade, default_league text not null default 'all', calendar_sync boolean not null default false, calendar_scope text not null default 'followed', event_reminder boolean not null default true, news_notifications boolean not null default true, updated_at timestamptz not null default now());
create table if not exists public.user_article_reads (user_id uuid not null references auth.users(id) on delete cascade, article_id text not null references public.articles(id), read_at timestamptz not null default now(), primary key(user_id,article_id));
create table if not exists public.ingestion_runs (id bigint generated by default as identity primary key, source text not null, status text not null check(status in ('running','succeeded','failed')), processed_count integer not null default 0, error_message text, started_at timestamptz not null default now(), finished_at timestamptz);
create index if not exists events_starts_at_idx on public.events(starts_at);
create index if not exists articles_published_at_idx on public.articles(published_at desc);

alter table public.leagues enable row level security; alter table public.entities enable row level security; alter table public.competitions enable row level security; alter table public.events enable row level security; alter table public.event_entities enable row level security; alter table public.articles enable row level security; alter table public.article_entities enable row level security; alter table public.user_follows enable row level security; alter table public.user_preferences enable row level security; alter table public.user_article_reads enable row level security; alter table public.ingestion_runs enable row level security;
drop policy if exists "public read" on public.leagues; create policy "public read" on public.leagues for select to anon,authenticated using(true);
drop policy if exists "public read" on public.entities; create policy "public read" on public.entities for select to anon,authenticated using(true);
drop policy if exists "public read" on public.competitions; create policy "public read" on public.competitions for select to anon,authenticated using(true);
drop policy if exists "public read" on public.events; create policy "public read" on public.events for select to anon,authenticated using(true);
drop policy if exists "public read" on public.event_entities; create policy "public read" on public.event_entities for select to anon,authenticated using(true);
drop policy if exists "public read" on public.articles; create policy "public read" on public.articles for select to anon,authenticated using(true);
drop policy if exists "public read" on public.article_entities; create policy "public read" on public.article_entities for select to anon,authenticated using(true);
drop policy if exists "owner access" on public.user_follows; create policy "owner access" on public.user_follows for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "owner access" on public.user_preferences; create policy "owner access" on public.user_preferences for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "owner access" on public.user_article_reads; create policy "owner access" on public.user_article_reads for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);

